/* ================= DISCO BALL + LOGO ================= */
function disco(id, big) {
  let s = 11, tiles = '';
  const rnd = () => (s = (s * 9301 + 49297) % 233280) / 233280;
  const cols = ['#FFFFFF', '#FFB3E0', '#FF6FC8', '#C9A8FF', '#8C6BFF', '#7FE3FF', '#5B3FD1', '#FFD2EF'];
  const n = big ? 12 : 8;
  for (let r = 0; r < n; r++) {
    const lat = -Math.PI / 2 + (r + .5) * Math.PI / n, w = Math.cos(lat), y = 50 + Math.sin(lat) * 46, h = 92 / n * (0.55 + .45 * w);
    const cnt = Math.max(3, Math.round(n * 1.6 * w));
    for (let c = 0; c < cnt; c++) {
      const u = -1 + (c + .5) * 2 / cnt, x = 50 + u * 46 * w, tw = 92 * w / cnt;
      const lit = Math.max(0, 1 - Math.hypot(x - 36, y - 32) / 60);
      const col = rnd() < lit * .9 ? '#FFFFFF' : cols[Math.floor(rnd() * cols.length)];
      tiles += `<rect x="${(x - tw / 2 + .5).toFixed(1)}" y="${(y - h / 2 + .5).toFixed(1)}" width="${(tw - 1).toFixed(1)}" height="${(h - 1).toFixed(1)}" rx=".8" fill="${col}" opacity="${(.55 + rnd() * .45).toFixed(2)}"/>`;
    }
  }
  return `<svg viewBox="0 0 100 100" aria-hidden="true"><defs>
    <radialGradient id="${id}b" cx="38%" cy="32%" r="70%"><stop offset="0" stop-color="#FFE6F7"/><stop offset=".45" stop-color="#B78CFF"/><stop offset="1" stop-color="#3B2394"/></radialGradient>
    <radialGradient id="${id}s" cx="50%" cy="50%" r="50%"><stop offset=".55" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#1B0F5C" stop-opacity=".55"/></radialGradient>
    <radialGradient id="${id}h" cx="34%" cy="28%" r="22%"><stop offset="0" stop-color="#fff" stop-opacity=".95"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>
    <clipPath id="${id}c"><circle cx="50" cy="50" r="46"/></clipPath></defs>
    <circle cx="50" cy="50" r="47" fill="url(#${id}b)"/><g clip-path="url(#${id}c)">${tiles}</g>
    <circle cx="50" cy="50" r="46" fill="url(#${id}s)"/><circle cx="50" cy="50" r="46" fill="url(#${id}h)"/>
    <path d="M30 22l1.6 4.4L36 28l-4.4 1.6L30 34l-1.6-4.4L24 28l4.4-1.6z" fill="#fff"/></svg>`;
}
let discoN = 0;
const LOGO = (size) => `<span class="logo" style="${size ? 'font-size:' + size : ''}"><span class="lp">PLAY</span><span class="lm">M</span><span class="lo">${disco('d' + (discoN++))}</span><span class="ld">DE</span></span>`;
const LOGO_SMALL_O = disco('dsm');

/* QR placeholder */
const QR = (() => {
  const n = 25; let s = 7, cells = '';
  const rnd = () => (s = (s * 9301 + 49297) % 233280) / 233280;
  const finder = (x, y) => `<rect x="${x}" y="${y}" width="7" height="7" fill="#10204A"/><rect x="${x + 1}" y="${y + 1}" width="5" height="5" fill="#fff"/><rect x="${x + 2}" y="${y + 2}" width="3" height="3" fill="#10204A"/>`;
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const inF = (x < 8 && y < 8) || (x > n - 9 && y < 8) || (x < 8 && y > n - 9);
    if (!inF && rnd() > .5) cells += `<rect x="${x}" y="${y}" width="1" height="1"/>`;
  }
  return `<svg viewBox="0 0 ${n} ${n}" width="100%" height="100%" fill="#10204A" shape-rendering="crispEdges">${cells}${finder(0, 0)}${finder(n - 7, 0)}${finder(0, n - 7)}</svg>`;
})();

